import { calculateUnitMargin } from './margin.js';
import { greetingForDate, weekdayForDate, firstName } from './greeting.js';
const $ = selector => document.querySelector(selector);
const state={user:null,csrf:null,page:'dashboard',params:{},config:{},products:[],team:[],testOrderId:null,testCheckout:false,skipTestResume:false};
const commerceOffsets={orders:0,products:0};
const pageNames={dashboard:'OVERZICHT',orders:'BESTELLINGEN',customers:'KLANTEN',tickets:'KLANTENSERVICE',returns:'RETOUREN',sandbox:'TESTBESTELLING',launch:'LIVEGANG',products:'PRODUCTSTATUS',sourcing:'INKOOP & LEVERANCIERS',commerce:'COMMERCE-ENGINE',templates:'ANTWOORDSJABLONEN',team:'TEAM',activity:'ACTIVITEITENLOG',settings:'INSTELLINGEN'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=n=>new Intl.NumberFormat('nl-NL',{style:'currency',currency:'EUR'}).format((Number(n)||0)/100);
const date=s=>s?new Intl.DateTimeFormat('nl-NL',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(s)):'—';
const dateTime=s=>s?new Intl.DateTimeFormat('nl-NL',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(s)):'—';
const badge=(value)=>`<span class="badge ${esc(value)}">${esc(({draft:'Concept',pending:'In behandeling',processing:'Verwerken',shipped:'Verzonden',delivered:'Afgeleverd',cancelled:'Geannuleerd',unpaid:'Niet betaald',paid:'Betaald',open:'Open',resolved:'Opgelost',closed:'Gesloten',urgent:'Urgent',high:'Hoog',requested:'Aangevraagd',approved:'Goedgekeurd',received:'Ontvangen',rejected:'Afgewezen',ready:'Verkoopklaar',archived:'Gearchiveerd',normal:'Normaal'})[value]||value)}</span>`;
const statusOptions=(values,current)=>values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(({draft:'Concept',pending:'In behandeling',processing:'Verwerken',shipped:'Verzonden',delivered:'Afgeleverd',cancelled:'Geannuleerd',open:'Open',resolved:'Opgelost',closed:'Gesloten',requested:'Aangevraagd',approved:'Goedgekeurd',received:'Ontvangen',rejected:'Afgewezen',ready:'Verkoopklaar',archived:'Gearchiveerd'})[v]||v)}</option>`).join('');
const head=(eyebrow,title,description,action='')=>`<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div><div class="actions">${action}</div></div>`;
const empty=(title,description)=>`<div class="empty"><div class="illustration">◇</div><strong>${title}</strong><p>${description}</p></div>`;
const panel=(title,content,right='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${right}</div>${state.page==='sandbox'?`<div class="sandbox-panel-body">${content}</div>`:content}</section>`;
const table=(headers,rows)=>`<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`;
function toast(message,error=false){const el=$('#notice');el.textContent=message;el.classList.toggle('error',error);el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4000)}
async function api(url,{method='GET',data}={}){
  const response=await fetch('/api'+url,{method,credentials:'same-origin',headers:{...(data?{'Content-Type':'application/json'}:{}),...(method!=='GET'&&state.csrf?{'X-KAP-CSRF':state.csrf}:{})},body:data?JSON.stringify(data):undefined});
  const result=await response.json().catch(()=>({error:'Onverwacht antwoord'}));
  if(!response.ok){if(response.status===401&&url!=='/login')showLogin();throw new Error(result.error||'Verzoek mislukt')}
  return result;
}
async function tryAction(run){try{await run()}catch(error){toast(error.message,true)}}
function showLogin(){$('#login').classList.remove('hidden');$('#shell').classList.add('hidden');state.user=null;state.csrf=null}
function showApp(){$('#login').classList.add('hidden');$('#shell').classList.remove('hidden');const sourcingNav=document.querySelector('[data-page="sourcing"]');if(sourcingNav)sourcingNav.style.display=['owner','manager'].includes(state.user.role)?'':'none';$('#user-name').textContent=state.user.name;$('#avatar').textContent=state.user.name[0]?.toUpperCase()||'K';if(state.demo){$('.sidebar-bottom strong').textContent='Tijdelijke demo';$('.sidebar-bottom small').textContent='Gegevens verdwijnen bij herstart'}}
function activationFromLink(){
  const params=new URLSearchParams(location.hash.replace(/^#/,''));
  const token=params.get('activate'),email=params.get('email');
  if(!token||!email)return false;
  // Remove the secret from browser history/address bar immediately.
  history.replaceState(null,'',location.pathname+location.search);
  $('.login-box').innerHTML=`<span class="eyebrow">EENMALIGE ACCOUNTINRICHTING</span><h2>Activeer je KAP. Studio<span>.</span></h2><p>Stel zelf een sterk wachtwoord in. Dit is geen GrowSocial-account.</p><form id="activation-form"><label>E-mailadres<input type="email" name="email" value="${esc(email)}" readonly></label><label>Nieuw wachtwoord<input type="password" name="password" autocomplete="new-password" minlength="14" maxlength="128" required placeholder="Minimaal 14 tekens"></label><label>Herhaal wachtwoord<input type="password" name="confirmation" autocomplete="new-password" minlength="14" maxlength="128" required></label><button class="primary" type="submit">Account activeren <span>↗</span></button></form><small>Deze beveiligde activatie is eenmalig en tijdelijk geldig.</small>`;
  $('#activation-form').addEventListener('submit',e=>{e.preventDefault();tryAction(async()=>{
    const f=new FormData(e.target),password=String(f.get('password'));
    if(password!==f.get('confirmation'))throw new Error('De wachtwoorden komen niet overeen');
    const result=await api('/setup/claim',{method:'POST',data:{token,email:f.get('email'),password}});
    e.target.reset();state.user=result.user;state.csrf=result.csrf;
    const s=await api('/session');state.csrf=s.csrf;state.demo=s.features?.demo;state.testCheckout=s.features?.testCheckout;
    showApp();await navigate('dashboard');toast('Je KAP. Studio-account is geactiveerd');
  })});
  return true;
}
async function start(){try{const r=await api('/session');state.user=r.user;state.csrf=r.csrf;state.demo=r.features?.demo;state.testCheckout=r.features?.testCheckout;showApp();await navigate('dashboard')}catch{showLogin()}}
$('#login-form').addEventListener('submit',e=>{e.preventDefault();tryAction(async()=>{const form=new FormData(e.target);const r=await api('/login',{method:'POST',data:{email:form.get('email'),password:form.get('password')}});state.user=r.user;state.csrf=r.csrf;const session=await api('/session');state.csrf=session.csrf;state.demo=session.features?.demo;state.testCheckout=session.features?.testCheckout;showApp();await navigate('dashboard');toast('Welkom in KAP. Studio')})});
$('#logout').addEventListener('click',()=>tryAction(async()=>{await api('/logout',{method:'POST',data:{}});showLogin()}));
$('#menu-button').addEventListener('click',()=>$('.sidebar').classList.toggle('open'));
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.page)));
document.addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeModal()});
const openModal=html=>{$('#modal-body').innerHTML=html;$('#modal').classList.remove('hidden')};
const closeModal=()=>{$('#modal').classList.add('hidden');$('#modal-body').innerHTML=''};
function setContent(html){$('#content').innerHTML=html}
async function navigate(page,params={}){
  state.page=page;state.params=params;$('#crumb').textContent=pageNames[page]||page;
  document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('.sidebar').classList.remove('open');
  setContent('<div class="empty">Gegevens laden…</div>');
  try{await views[page]()}catch(e){setContent(head('KAP. STUDIO','Er ging iets mis',e.message));toast(e.message,true)}
}
const views={dashboard,orders,customers,tickets,returns,sandbox,launch,products,sourcing,commerce,templates,team,activity,settings};

async function commerce(){
  const status=await api('/commerce/status');
  const title=head('KAP. / COMMERCE-ENGINE','Medusa-koppeling','De handelsmotor en de eigen KAP. klantenservice blijven bewust gescheiden.');
  const warning='<div class="info-callout"><strong>Alleen-lezen integratie.</strong> De reguliere bestellingen en productstatus in KAP. Studio komen nog uit onze eigen database. Deze pagina activeert geen webshopcheckout, betaling, voorraadmutatie of retourbetaling.</div>';
  if(!status.configured){
    setContent(title+warning+panel('Medusa v2 — nog niet gekoppeld',empty('Veilige integratie voorbereid','Configureer eerst een aparte Medusa v2-server en een secret API key. Tot die tijd blijft onze bestaande KAP. Studio zelfstandig werken.')));
    return;
  }
  const [orders,products]=await Promise.all([api('/commerce/orders?offset='+commerceOffsets.orders),api('/commerce/products?offset='+commerceOffsets.products)]);
  const money=o=>o.currency==='EUR'&&o.total_cents!==null?euro(o.total_cents):'—';
  const orderRows=orders.items.map(o=>`<tr><td><strong>${esc(o.display_id??o.id)}</strong><div class="muted">${dateTime(o.created_at)}</div></td><td>${esc(o.email)}</td><td>${esc(o.payment_status)}</td><td>${esc(o.fulfillment_status)}</td><td>${money(o)}</td></tr>`).join('');
  const productRows=products.items.map(p=>`<tr><td><strong>${esc(p.title)}</strong></td><td>${esc(p.status)}</td><td>${p.variants}</td></tr>`).join('');
  const pager=(kind,result)=>{
    const first=result.shown?result.offset+1:0,last=result.offset+result.shown;
    const previous=result.offset>0?`<button class="secondary" data-commerce-page="${kind}" data-commerce-offset="${Math.max(0,result.offset-30)}">← Vorige</button>`:'';
    const next=result.has_more?`<button class="secondary" data-commerce-page="${kind}" data-commerce-offset="${result.offset+30}">Volgende →</button>`:'';
    return `<div class="split-actions"><span class="muted">${first}–${last} van ${result.total}</span><div class="actions">${previous}${next}</div></div>`;
  };
  setContent(title+warning+
    panel(`Medusa-bestellingen (${orders.total})`,(orders.items.length?table(['Order','Klant','Betaling','Levering','Totaal'],orderRows):empty('Geen bestellingen op deze pagina','Blader terug of voeg een testbestelling toe in de afzonderlijke Medusa-testomgeving.'))+pager('orders',orders))+
    panel(`Medusa-producten (${products.total})`,(products.items.length?table(['Product','Status','Varianten'],productRows):empty('Geen producten op deze pagina','Blader terug of voeg een testproduct toe in de afzonderlijke Medusa-testomgeving.'))+pager('products',products)));
  document.querySelectorAll('[data-commerce-page]').forEach(button=>button.addEventListener('click',()=>tryAction(async()=>{
    const kind=button.dataset.commercePage,offset=Number(button.dataset.commerceOffset);
    if(!['orders','products'].includes(kind)||!Number.isSafeInteger(offset)||offset<0)return;
    commerceOffsets[kind]=offset;await commerce();
  })));
}

async function dashboard(){
  const r=await api('/dashboard');$('#order-badge').textContent=r.orders.active||'';$('#ticket-badge').textContent=r.tickets.open||'';
  const metrics=[['Bestellingen',r.orders.total,'Alle aangemaakte orders'],['Actieve orders',r.orders.active,'Nog te verwerken'],['Open klantvragen',r.tickets.open,`${r.tickets.urgent} met hoge prioriteit`],['Ontvangen omzet',euro(r.orders.paid_total),'Alleen geregistreerd betaald']];
  const cards=`<div class="cards">${metrics.map(m=>`<div class="card"><div class="card-title">${m[0]}</div><div class="metric">${m[1]}</div><div class="metric-bottom">${m[2]}</div></div>`).join('')}</div>`;
  const ordersBody=r.recent_orders.length?table(['Order','Klant','Status','Totaal'],r.recent_orders.map(o=>`<tr data-id="${o.id}" data-kind="order"><td><strong>#${o.number}</strong><div class="muted">${date(o.created_at)}</div></td><td>${esc(o.first_name+' '+o.last_name)}<div class="muted">${esc(o.email)}</div></td><td>${badge(o.status)}</td><td><strong>${euro(o.total_cents)}</strong></td></tr>`).join('')):empty('Nog geen orders','Nieuwe orders verschijnen automatisch zodra een veilige orderkoppeling actief is.');
  const ticketsBody=r.recent_tickets.length?table(['Ticket','Onderwerp','Status'],r.recent_tickets.map(t=>`<tr data-id="${t.id}" data-kind="ticket"><td><strong>#${t.number}</strong></td><td>${esc(t.subject)}<div class="muted">${esc(t.email||'Intern')}</div></td><td>${badge(t.status)}</td></tr>`).join('')):empty('Nog geen klantvragen','Maak handmatig tickets aan of koppel een eigen KAP.-mailbox.');
  setContent(head(weekdayForDate().toUpperCase()+' / KAP. OPERATIONS',greetingForDate()+', '+esc(firstName(state.user.name))+'.','Je dagelijkse overzicht van bestellingen, klanten en service.')+(state.demo?'<div class="info-callout"><strong>Dit is een tijdelijke demo met fictieve gegevens.</strong> Bij inactiviteit of herstart worden wijzigingen gewist. Niet gebruiken voor echte klanten, bestellingen of e-mails.</div>':'')+cards+`<div class="dashboard-grid">${panel('Recente bestellingen',ordersBody,'<a href="#" data-go="orders">Alles bekijken ↗</a>')}${panel('Klantenservice',ticketsBody,'<a href="#" data-go="tickets">Inbox openen ↗</a>')}</div><div class="info-callout"><strong>Pre-launch veiligheidsmodus.</strong> Publieke bestellingen en echte betalingen blijven uitgeschakeld. ${state.testCheckout&&['owner','manager'].includes(state.user.role)?'<a href="#" data-go="sandbox">Probeer een volledige fictieve testbestelling ↗</a>':'<a href="#" data-go="launch">Bekijk de livegang-checklist ↗</a>'}</div>`);
  bindRows();bindLinks();
}
function bindLinks(){document.querySelectorAll('[data-go]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();navigate(a.dataset.go)}))}
function bindRows(){document.querySelectorAll('tr[data-id]').forEach(row=>row.addEventListener('click',()=>tryAction(()=>row.dataset.kind==='order'?orderDetail(row.dataset.id):row.dataset.kind==='ticket'?ticketDetail(row.dataset.id):row.dataset.kind==='customer'?customerDetail(row.dataset.id):returnDetail(row.dataset.id))))}
function wireFilter(callback){let timer;$('#search')?.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(callback,250)});$('#status')?.addEventListener('change',callback)}

async function orders(){
  const q=state.params.q||'',status=state.params.status||'all';const r=await api('/orders?'+new URLSearchParams({q,status}));
  const rows=r.items.map(o=>`<tr data-id="${o.id}" data-kind="order"><td><strong>#${o.number}</strong>${o.source==='sandbox'?' <span class="badge">TEST</span>':''}<div class="muted">${dateTime(o.created_at)}</div></td><td>${esc([o.first_name,o.last_name].filter(Boolean).join(' ')||o.email)}<div class="muted">${esc(o.email)}</div></td><td>${badge(o.status)}</td><td>${badge(o.payment_status)}</td><td>${euro(o.total_cents)}</td></tr>`).join('');
  setContent(head('SALES / FULFILLMENT','Bestellingen','Beheer je orderflow van binnenkomst tot levering.','<button class="primary" id="new-order">+ Conceptorder</button>')+`<div class="filters"><input id="search" class="field search-field" placeholder="Zoek ordernummer of e-mail" value="${esc(q)}"><select id="status" class="field">${statusOptions(['all','draft','pending','processing','shipped','delivered','cancelled'],status)}</select></div>`+panel(`${r.items.length} bestellingen`,r.items.length?table(['Order','Klant','Orderstatus','Betaling','Totaal'],rows):empty('Nog geen bestellingen','Maak een conceptorder aan om de workflow te testen.')));
  $('#new-order').addEventListener('click',()=>tryAction(newOrderModal));bindRows();wireFilter(()=>navigate('orders',{q:$('#search').value,status:$('#status').value}));
}
async function newOrderModal(){
  const products=(await api('/products')).items.filter(p=>p.status!=='archived');
  openModal(`<span class="eyebrow">HANDMATIGE INVOER</span><h2>Nieuwe conceptorder</h2><p class="muted">Er wordt niets betaald of verzonden. Productprijzen zijn voorlopig.</p><form id="create-order" class="form-grid"><label>Voornaam<input class="field" name="first_name"></label><label>Achternaam<input class="field" name="last_name"></label><label class="wide">E-mailadres<input type="email" class="field" name="email" required></label><label class="wide">Product<select name="sku" class="field">${products.map(p=>`<option value="${esc(p.sku)}">${esc(p.title)} — ${euro(p.price_cents)}</option>`).join('')}</select></label><label>Aantal<input type="number" name="quantity" class="field" min="1" max="100" value="1" required></label><label>Verzendkosten in €<input type="number" name="shipping" class="field" min="0" step="0.01" value="0"></label><div class="wide"><button class="primary" type="submit">Conceptorder opslaan ↗</button></div></form>`);
  $('#create-order').addEventListener('submit',e=>{e.preventDefault();tryAction(async()=>{const f=new FormData(e.target);await api('/orders',{method:'POST',data:{customer:{email:f.get('email'),first_name:f.get('first_name'),last_name:f.get('last_name')},items:[{sku:f.get('sku'),quantity:Number(f.get('quantity'))}],shipping_cents:Math.round(Number(f.get('shipping'))*100)}});closeModal();toast('Conceptorder aangemaakt');await navigate('orders')})});
}
async function orderDetail(id){
  const r=await api('/orders/'+id),o=r.item,c=o.customer;
  const form=`<form id="order-update" class="form-grid"><label>Orderstatus<select class="field" name="status">${statusOptions(['draft','pending','processing','shipped','delivered','cancelled'],o.status)}</select></label><label>Fulfillment<select class="field" name="fulfillment_status">${statusOptions(['unfulfilled','partial','fulfilled','returned'],o.fulfillment_status)}</select></label><label>Vervoerder<input class="field" name="carrier" value="${esc(o.carrier)}"></label><label>Track & trace<input class="field" name="tracking_code" value="${esc(o.tracking_code)}"></label><div class="wide"><button class="primary" type="submit">Wijzigingen bewaren ↗</button></div></form>`;
  openModal(`<span class="eyebrow">ORDER #${o.number} / ${date(o.created_at)}</span><h2>Bestelling #${o.number}</h2>${badge(o.status)} ${badge(o.payment_status)}<div class="detail-grid"><div class="detail"><small>Klant</small><strong>${esc(c.first_name+' '+c.last_name)}</strong><div class="muted">${esc(c.email)}</div></div><div class="detail"><small>Totaal</small><strong>${euro(o.total_cents)}</strong><div class="muted">${esc(o.source)}</div></div></div><h3>Artikelen</h3>${table(['Artikel','Aantal','Totaal'],r.items.map(i=>`<tr><td>${esc(i.title)}</td><td>${i.quantity}</td><td>${euro(i.line_total_cents)}</td></tr>`).join(''))}<h3>Verwerken</h3>${form}<h3>Bestelmails</h3>${r.notifications.length?r.notifications.map(n=>`<div class="list-card"><strong>${esc(n.subject)}</strong><p>${esc(n.recipient)} · ${esc(n.delivery_status==='simulated'?'Alleen simulatie — niet verzonden':n.delivery_status==='provider_accepted'?'Door mailprovider geaccepteerd':n.delivery_status==='queued'?'Wacht op eigen KAP.-mailprovider':'Levering onbekend/mislukt')}</p></div>`).join(''):empty('Nog geen bestelmails','Een bestelbevestiging wordt voorbereid zodra een betaling is bevestigd.')}<h3>Gekoppelde klantenservice</h3>${r.tickets.length?r.tickets.map(t=>`<div class="list-card">#${t.number} · ${esc(t.subject)} ${badge(t.status)}</div>`).join(''):empty('Nog geen klantvragen','')}<h3>Retouren</h3>${r.returns.length?r.returns.map(a=>`<div class="list-card">${esc(a.reason)} ${badge(a.status)}</div>`).join(''):empty('Geen retouren','')}<h3>Activiteiten</h3><ul class="timeline">${r.events.map(e=>`<li><strong>${esc(e.action)}</strong> · ${esc(e.actor||'Systeem')}<small>${dateTime(e.created_at)}</small></li>`).join('')}</ul><div class="info-callout">Een orderstatus aanpassen voert geen betaling of terugbetaling uit. Verzenden vereist een bevestigde betaling.</div>`);
  $('#order-update').addEventListener('submit',e=>{e.preventDefault();tryAction(async()=>{const f=Object.fromEntries(new FormData(e.target));await api('/orders/'+id,{method:'PATCH',data:f});closeModal();toast('Order bijgewerkt');await navigate('orders')})});
}

async function sandbox(){
  if(!state.testCheckout||!['owner','manager'].includes(state.user.role)){setContent(head('KAP. / QA','Testbestelling','De testcheckout is alleen beschikbaar voor bevoegd KAP.-personeel als die expliciet is ingeschakeld.')+`<div class="info-callout">Op de echte webshop blijft bestellen geblokkeerd totdat de producten, betaalprovider en operationele controles zijn vrijgegeven.</div>`);return}
  const products=(await api('/products')).items.filter(p=>p.status!=='archived');
  if(!state.testOrderId&&!state.skipTestResume){const previous=await api('/testing/orders/latest');if(previous.item)state.testOrderId=previous.item.id}
  let r=null;
  if(state.testOrderId){try{r=await api('/orders/'+state.testOrderId)}catch{state.testOrderId=null}}
  const o=r?.item;
  const steps=`<div class="sandbox-steps"><div class="sandbox-step active"><strong>01</strong><span>Product kiezen</span></div><div class="sandbox-step ${o?'active':''}"><strong>02</strong><span>Checkout</span></div><div class="sandbox-step ${o?.payment_status==='paid'?'active':''}"><strong>03</strong><span>Testbetaling</span></div><div class="sandbox-step ${o?.status==='shipped'||o?.status==='delivered'?'active':''}"><strong>04</strong><span>Verzending</span></div></div>`;
  const intro=`<div class="info-callout"><strong>100% simulatie, €0 afgeschreven.</strong> Alleen een fictieve klant en voorbeeldproducten. De echte webshop blijft gesloten; klantmails worden hier uitsluitend voorbereid, nooit verzonden. ${state.demo?'Deze tijdelijke demo verliest testorders na een herstart.':'Testorders blijven opgeslagen in de KAP.-database en tellen niet mee als echte omzet.'}</div>`;
  if(!o){
    setContent(head('KAP. / END-TO-END TEST','Van product tot levering','Loop zelf door de volledige verkoopflow zonder product, betaalprovider of echte klantgegevens.')+intro+steps+panel('01 · Voorbeeldproductpagina',`<p class="muted">Kies een product zoals een bezoeker dat op KAP. zou doen. De server bepaalt altijd de prijs.</p><form id="sandbox-cart" class="form-grid"><label class="wide">Product<select class="field" name="sku">${products.map(p=>`<option value="${esc(p.sku)}">${esc(p.title)} · ${euro(p.price_cents)}</option>`).join('')}</select></label><label>Aantal<input class="field" type="number" name="quantity" min="1" max="5" value="1" required></label><div class="wide"><button class="primary">Verder naar testcheckout ↗</button></div></form><p class="muted">Testklant: KAP Testklant · testbestelling@voorbeeld.invalid</p>`));
    $('#sandbox-cart').addEventListener('submit',e=>{e.preventDefault();tryAction(async()=>{const f=new FormData(e.target);const result=await api('/testing/checkout',{method:'POST',data:{sku:f.get('sku'),quantity:Number(f.get('quantity'))}});state.testOrderId=result.item.id;state.skipTestResume=false;toast('Fictieve order aangemaakt');await sandbox()})});return;
  }
  const confirmation=r.notifications.filter(n=>n.kind==='order_confirmation');const shipping=r.notifications.filter(n=>n.kind==='shipping_confirmation');
  const orderPanel=panel(`02 · Testcheckout — bestelling #${o.number}`,`<div class="detail-grid"><div class="detail"><small>Klant (fictief)</small><strong>KAP Testklant</strong><div class="muted">testbestelling@voorbeeld.invalid</div></div><div class="detail"><small>Ordertotaal</small><strong>${euro(o.total_cents)}</strong><div class="muted">Inclusief btw · voorbeeldprijs</div></div></div>${table(['Artikel','Aantal','Bedrag'],r.items.map(i=>`<tr><td>${esc(i.title)}</td><td>${i.quantity}</td><td>${euro(i.line_total_cents)}</td></tr>`).join(''))}<div class="split-actions"><button class="secondary" id="sandbox-open-order">Bekijk in bestellingen ↗</button><button class="secondary" id="sandbox-new">Start nieuwe test</button></div>`);
  const paymentPanel=panel('03 · Betaling zonder echt geld',o.payment_status!=='paid'?`<p>De betaling staat op <strong>niet betaald</strong>. Test hoe KAP. een succesvolle betaling verwerkt, zonder iDEAL of een betaalprovider aan te spreken.</p><button class="primary" id="sandbox-pay">Simuleer geslaagde betaling (€0) ↗</button>`:`<p>${badge('paid')} · Alleen teststatus; er is niets afgeschreven.</p><div class="list-card"><strong>Automatische bestelbevestiging</strong><p>${confirmation.length?'Status: '+esc(confirmation[0].delivery_status)+' · geen echte e-mail verzonden':'Notificatie wordt aangemaakt na betaling.'}</p>${confirmation.length?`<details><summary>Bekijk voorbereide e-mail</summary><pre class="sandbox-email">${esc(confirmation[0].body)}</pre></details>`:''}</div>`);
  const shipPanel=o.payment_status==='paid'?panel('04 · Orderverwerking en verzending',`<p>Huidige status: ${badge(o.status)}. Verzenden legt een vervoerder en track & trace vast en bereidt de verzendmail voor.</p>${o.status==='shipped'||o.status==='delivered'?`<div class="list-card">${badge(o.status)} <strong>${esc(o.carrier||'Testvervoerder')}</strong><p>${esc(o.tracking_code)}</p>${shipping.length?`<details><summary>Bekijk verzendbevestiging (${esc(shipping[0].delivery_status)})</summary><pre class="sandbox-email">${esc(shipping[0].body)}</pre></details>`:''}</div>`:`<form id="sandbox-ship" class="form-grid"><label>Vervoerder<input class="field" name="carrier" value="KAP Testtransport" required></label><label>Track & trace<input class="field" name="tracking_code" value="KAP-TEST-0001" required></label><div class="wide"><button class="primary">Markeer als verzonden ↗</button></div></form>`}`):'';
  const afterSales=o.payment_status==='paid'?panel('05 · Klantenservice en retouren',`<p>Test de vervolgstappen op dezelfde order. Alle handelingen blijven intern en fictief.</p><div class="split-actions"><button class="secondary" id="sandbox-ticket">Koppel klantvraag</button><button class="secondary" id="sandbox-return">Registreer testretour</button></div><div class="detail-grid"><div class="detail"><small>Gekoppelde tickets</small><strong>${r.tickets.length}</strong></div><div class="detail"><small>Retouraanvragen</small><strong>${r.returns.length}</strong></div></div>`):'';
  setContent(head('KAP. / END-TO-END TEST','Testbestelling doorlopen','Van een voorbeeldproduct via gesimuleerde betaling naar orderbeheer, verzendmail en retour.')+intro+steps+orderPanel+paymentPanel+shipPanel+afterSales);
  $('#sandbox-new').addEventListener('click',()=>{state.testOrderId=null;state.skipTestResume=true;sandbox()});
  $('#sandbox-open-order').addEventListener('click',()=>tryAction(()=>orderDetail(o.id)));
  $('#sandbox-pay')?.addEventListener('click',()=>tryAction(async()=>{await api('/testing/orders/'+o.id+'/pay',{method:'POST',data:{}});toast('Testbetaling gesimuleerd, bevestigingsmail voorbereid');await sandbox()}));
  $('#sandbox-ship')?.addEventListener('submit',e=>{e.preventDefault();tryAction(async()=>{const f=new FormData(e.target);await api('/orders/'+o.id,{method:'PATCH',data:{status:'shipped',fulfillment_status:'fulfilled',carrier:f.get('carrier'),tracking_code:f.get('tracking_code')}});toast('Testorder verzonden en verzendmail voorbereid');await sandbox()})});
  $('#sandbox-ticket')?.addEventListener('click',()=>tryAction(async()=>{await api('/tickets',{method:'POST',data:{order_id:o.id,subject:'Testvraag over bestelling #'+o.number,priority:'normal'}});toast('Ticket gekoppeld aan dezelfde order');await sandbox()}));
  $('#sandbox-return')?.addEventListener('click',()=>tryAction(async()=>{await api('/returns',{method:'POST',data:{order_id:o.id,reason:'Testretour — demonstratie'}});toast('Testretour gekoppeld');await sandbox()}));
}

